function MillHopperLevelFloatMaker.init() MillHopperLevelFloatMaker.ironStock=12; MillHopperLevelFloatMaker.bronzeStock=10; MillHopperLevelFloatMaker.woodStock=14; MillHopperLevelFloatMaker.leatherStock=10; MillHopperLevelFloatMaker.silverStock=8; MillHopperLevelFloatMaker.goldStock=6; MillHopperLevelFloatMaker.jewelStock=4; MillHopperLevelFloatMaker.pearlStock=4; MillHopperLevelFloatMaker.productStock={}; MillHopperLevelFloatMaker.buildings={}; MillHopperLevelFloatMaker.maker=nil; MillHopperLevelFloatMaker.activeMaking={}; MillHopperLevelFloatMaker.totalProducts=0; MillHopperLevelFloatMaker.dayTimer=0; print("[MillHopperLevelFloatMaker] Royal Mill Hopper Level Float Maker System initialized (6 products, 4 buildings)") end
function MillHopperLevelFloatMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillHopperLevelFloatMaker.maker={name=n or ("Plavcar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plavcar najet: %s (spretnost: %d)",MillHopperLevelFloatMaker.maker.name,s),"success") end; return true end
function MillHopperLevelFloatMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillHopperLevelFloatMaker.build(id) local ok,e=MillHopperLevelFloatMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillHopperLevelFloatMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillHopperLevelFloatMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillHopperLevelFloatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillHopperLevelFloatMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillHopperLevelFloatMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillHopperLevelFloatMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillHopperLevelFloatMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillHopperLevelFloatMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillHopperLevelFloatMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillHopperLevelFloatMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillHopperLevelFloatMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillHopperLevelFloatMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillHopperLevelFloatMaker.buildings==0 then return false,"Potrebna plavcna delavnica" end; if not MillHopperLevelFloatMaker.maker then return false,"Potreben plavcar" end; return true end
function MillHopperLevelFloatMaker.make(pt,qty) qty=qty or 1; local ok,e=MillHopperLevelFloatMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillHopperLevelFloatMaker.ironStock=MillHopperLevelFloatMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillHopperLevelFloatMaker.bronzeStock=MillHopperLevelFloatMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillHopperLevelFloatMaker.woodStock=MillHopperLevelFloatMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillHopperLevelFloatMaker.leatherStock=MillHopperLevelFloatMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillHopperLevelFloatMaker.silverStock=MillHopperLevelFloatMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillHopperLevelFloatMaker.goldStock=MillHopperLevelFloatMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillHopperLevelFloatMaker.jewelStock=MillHopperLevelFloatMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillHopperLevelFloatMaker.pearlStock=MillHopperLevelFloatMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillHopperLevelFloatMaker.maker then t=math.max(1,t-math.floor(MillHopperLevelFloatMaker.maker.skill/13)) end; table.insert(MillHopperLevelFloatMaker.activeMaking,{id="millhopperlevelfloat_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillHopperLevelFloatMaker.completeMaking(m) local q=1.0+(MillHopperLevelFloatMaker.getQualityBonus()/100); if MillHopperLevelFloatMaker.maker then q=q+(MillHopperLevelFloatMaker.maker.skill/140) end; q=math.min(2.5,q); MillHopperLevelFloatMaker.productStock[m.productType]=(MillHopperLevelFloatMaker.productStock[m.productType] or 0)+m.quantity; MillHopperLevelFloatMaker.totalProducts=MillHopperLevelFloatMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillHopperLevelFloatMaker.maker then MillHopperLevelFloatMaker.maker.itemsMade=MillHopperLevelFloatMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillHopperLevelFloatMaker.maker.skill=math.min(100,MillHopperLevelFloatMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plavec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millhopperlevelfloat.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillHopperLevelFloatMaker.update(dt) if not _G.state then return end; MillHopperLevelFloatMaker.dayTimer=MillHopperLevelFloatMaker.dayTimer+dt; if MillHopperLevelFloatMaker.dayTimer>=30 then MillHopperLevelFloatMaker.dayTimer=0; for i=#MillHopperLevelFloatMaker.activeMaking,1,-1 do local m=MillHopperLevelFloatMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillHopperLevelFloatMaker.completeMaking(m); table.remove(MillHopperLevelFloatMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillHopperLevelFloatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillHopperLevelFloatMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
